def parse_nested_parens(paren_string: str) -> List[int]:
    """ Given a string with various groups of nested parentheses separated by spaces, this function finds the maximum nesting depth for each group.
    For each group, the deepest level of parentheses is determined.
    For example, the group '(()())' has a maximum nesting depth of 2, and '((()))' has a depth of 3.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    depths = []
    for group in paren_string.split():
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths",
